package sfz.shard.l03.demo

import java.nio.ByteBuffer
import java.security.MessageDigest
import java.util.TreeMap

fun md5(key: String): Long = ByteBuffer.wrap(MessageDigest.getInstance("MD5").digest(key.toByteArray())).long

/** Ten nodes hold 100,000 payment keys. An eleventh joins. How many keys move, and who sends them? */
fun main() {
    val ten = (1..10).map { "node-%02d".format(it) }
    val eleven = ten + "node-11"
    val keys = (0 until 100_000).map { "pay-$it" }

    fun report(name: String, before: (String) -> String, after: (String) -> String) {
        val moved = keys.filter { before(it) != after(it) }
        val senders = moved.map(before).toSet().size
        val toNew = moved.count { after(it) == "node-11" }
        println("%-26s %,6d keys move (%4.1f%%), %,6d of them to node-11, sent by %2d %s"
            .format(name, moved.size, moved.size / 1_000.0, toNew, senders, if (senders == 1) "node" else "nodes"))
    }

    // lesson 1: node = hash mod N
    report("hash mod N", { ten[Math.floorMod(md5(it), 10L).toInt()] }, { eleven[Math.floorMod(md5(it), 11L).toInt()] })

    // fixed partitions: 1,000 of them; a key's partition never changes, whole partitions change node
    val owner = Array(1_000) { ten[it % 10] }
    val before = owner.copyOf()
    var given = 0
    while (given < 1_000 / 11) { // node-11 takes 90 partitions, one at a time from the busiest node
        val donor = ten.maxBy { n -> owner.count { it == n } }
        owner[owner.indices.last { owner[it] == donor }] = "node-11"
        given++
    }
    val partition = { key: String -> Math.floorMod(md5(key), 1_000L).toInt() }
    report("1,000 fixed partitions", { before[partition(it)] }, { owner[partition(it)] })

    // lesson 2: a ring with T tokens per node
    for (t in listOf(1, 16)) {
        fun ring(nodes: List<String>) = TreeMap<Long, String>().apply { nodes.forEach { n -> repeat(t) { put(md5("$n#$it"), n) } } }
        val r10 = ring(ten)
        val r11 = ring(eleven)
        val owner = { r: TreeMap<Long, String>, k: String -> (r.ceilingEntry(md5(k)) ?: r.firstEntry()).value }
        report("ring, $t token(s) per node", { owner(r10, it) }, { owner(r11, it) })
    }
}

package sfz.shard.l03.demo

/** Fixed partitions spread over N nodes: the busiest node holds ceil(P / N), the quietest floor(P / N). */
fun main() {
    println("partitions  nodes  per node (min to max)  busiest node vs average")
    for (p in listOf(12, 480, 512)) {
        for (n in listOf(5, 13, 32, 40, 48, 96)) {
            val min = p / n
            val max = (p + n - 1) / n
            val ratio = max / (p.toDouble() / n)
            val note = if (min == 0) "  <- some nodes hold nothing" else ""
            println("%10d  %5d  %9d to %-9d  %22.2f%s".format(p, n, min, max, ratio, note))
        }
    }
}

package sfz.shard.l03.demo

/**
 * Five nodes, 20 partitions of 220 requests a second each: 880 a second per node, against a capacity
 * of 1,000. At second 1, one merchant in partition 7 (on node-3) triples that partition's traffic.
 * A node over capacity answers health checks late, so the failure detector calls it dead.
 */
fun main() {
    val capacity = 1_000.0
    for (automatic in listOf(true, false)) {
        val load = MutableList(20) { 220.0 }
        val owner = MutableList(20) { "node-${it % 5 + 1}" }
        val alive = (1..5).map { "node-$it" }.toSortedSet()
        println(if (automatic) "automatic: move a dead node's partitions to the others" else "manual: alert a person, move nothing")
        for (second in 0..3) {
            if (second == 1) load[7] = 660.0 // the hot merchant
            val perNode = alive.associateWith { n -> owner.indices.filter { owner[it] == n }.sumOf { load[it] } }
            val served = perNode.values.sumOf { minOf(it, capacity) }
            println("  second $second: %s  served %,.0f of %,.0f a second".format(
                perNode.entries.joinToString(" ") { "${it.key}=%.0f".format(it.value) }.ifEmpty { "no nodes left" }, served, load.sum()))
            if (!automatic) continue
            val dead = perNode.filter { it.value > capacity }.keys
            alive -= dead
            if (alive.isEmpty()) continue
            // the "fix": hand every partition of a dead node to the least loaded survivor, one at a time
            for (p in owner.indices.filter { owner[it] in dead }) {
                owner[p] = alive.minBy { n -> owner.indices.filter { owner[it] == n }.sumOf { load[it] } }
            }
        }
    }
}

package sfz.shard.l03.demo

/** Three nodes, 16 slots. Slot 0 moves from A to C while a client keeps reading it. */
fun main() {
    val slotOf = { key: String -> Math.floorMod(md5(key), 16L).toInt() }
    val owner = Array(16) { listOf("A", "B", "C")[it * 3 / 16] }
    val stores = mapOf("A" to HashMap<String, String>(), "B" to HashMap(), "C" to HashMap())
    val keys = (0 until 300).map { "pay-$it" }.filter { slotOf(it) == 0 }.sorted().take(3)
    keys.forEach { stores.getValue(owner[0])[it] = "value of $it" }
    var migratingTo: String? = null

    // the server side: what node answers to GET key
    fun serve(node: String, key: String, asking: Boolean): String {
        val slot = slotOf(key)
        return when {
            owner[slot] == node && migratingTo != null && key !in stores.getValue(node) -> "ASK $slot $migratingTo"
            owner[slot] == node -> "\"${stores.getValue(node)[key]}\""
            migratingTo == node && asking -> "\"${stores.getValue(node)[key]}\""
            else -> "MOVED $slot ${owner[slot]}"
        }
    }

    // the client: its own slot map; MOVED updates it, ASK doesn't
    val slotMap = owner.copyOf()
    fun get(key: String) {
        var node = slotMap[slotOf(key)]
        var asking = false
        val trace = StringBuilder("GET $key")
        while (true) {
            val reply = serve(node, key, asking)
            trace.append(" -> ${if (asking) "ASKING, " else ""}$node: $reply")
            val parts = reply.split(" ")
            when (parts[0]) {
                "MOVED" -> { slotMap[parts[1].toInt()] = parts[2]; node = parts[2]; asking = false }
                "ASK" -> { node = parts[2]; asking = true }
                else -> break
            }
        }
        println("  $trace   (client map: slot 0 on ${slotMap[0]})")
    }

    println("before the migration")
    keys.forEach(::get)
    println("slot 0 starts moving to C; ${keys[0]} has been copied")
    migratingTo = "C"
    stores.getValue("C")[keys[0]] = stores.getValue("A").remove(keys[0])!!
    keys.forEach(::get)
    println("the rest are copied, and C owns slot 0")
    keys.drop(1).forEach { stores.getValue("C")[it] = stores.getValue("A").remove(it)!! }
    owner[0] = "C"
    migratingTo = null
    keys.forEach(::get)
}

