fun get(key: String): String? {
    var node = slotMap[slotOf(key)]
    var asking = false
    repeat(6) {
        when (val r = send(node, key, asking)) {
            is Reply.Value -> return r.value
            is Reply.Moved -> { slotMap[r.slot] = r.node; node = r.node; asking = false } // the slot moved for good
            is Reply.Ask -> { node = r.node; asking = true }                              // this key, this once
        }
    }
    throw IllegalStateException("too many redirects for $key")
}
// During a migration most of the slot's keys are still on the old owner;
// pointing the map at the new owner would bounce all of them back with MOVED.
